import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import { AppDispatch, RootState } from '../store';
import { fetchSessions } from '../store/sessionSlice';
import { fetchConnections } from '../store/connectionSlice';

const Dashboard: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { user } = useSelector((state: RootState) => state.auth);
  const { sessions, loading: sessionsLoading } = useSelector((state: RootState) => state.sessions);
  const { connections, loading: connectionsLoading } = useSelector((state: RootState) => state.connections);

  useEffect(() => {
    dispatch(fetchSessions());
    dispatch(fetchConnections());
  }, [dispatch]);

  // Get recent sessions (last 3)
  const recentSessions = sessions.slice(0, 3);

  // Get pending connections
  const pendingConnections = connections.filter(
    (connection) => connection.status === 'pending' && connection.recipientId === user?.id
  );

  return (
    <div className="max-w-4xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Welcome Card */}
        <div className="bg-gradient-to-r from-teal-500 to-blue-500 rounded-lg shadow-lg p-6 text-white col-span-1 md:col-span-2">
          <h1 className="text-3xl font-bold mb-2">Welcome, {user?.pseudonym}!</h1>
          <p className="text-white/90">
            Coco is here to help you navigate your relationships with care and insight.
          </p>
        </div>

        {/* Quick Actions */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Quick Actions</h2>
          <div className="space-y-4">
            <Link
              to="/sessions/new"
              className="block w-full text-center py-3 px-4 bg-teal-100 text-teal-800 font-medium rounded-md hover:bg-teal-200 transition-colors"
            >
              Start New Conversation
            </Link>
            <Link
              to="/connections/new"
              className="block w-full text-center py-3 px-4 bg-blue-100 text-blue-800 font-medium rounded-md hover:bg-blue-200 transition-colors"
            >
              Invite Connection
            </Link>
          </div>
        </div>

        {/* Pending Connections */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">
            Pending Invitations
            {pendingConnections.length > 0 && (
              <span className="ml-2 px-2 py-1 bg-yellow-100 text-yellow-800 text-xs font-semibold rounded-full">
                {pendingConnections.length} New
              </span>
            )}
          </h2>
          {connectionsLoading ? (
            <p className="text-gray-500">Loading connections...</p>
          ) : pendingConnections.length === 0 ? (
            <p className="text-gray-500">No pending invitations</p>
          ) : (
            <ul className="space-y-3">
              {pendingConnections.map((connection) => (
                <li key={connection.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-md">
                  <div>
                    <p className="font-medium">{connection.creator.pseudonym}</p>
                    <p className="text-sm text-gray-500">
                      Wants to connect as: {connection.relationshipType}
                    </p>
                  </div>
                  <div className="flex space-x-2">
                    <button
                      className="px-3 py-1 bg-teal-100 text-teal-800 rounded-md hover:bg-teal-200"
                      onClick={() => {/* Accept connection logic */}}
                    >
                      Accept
                    </button>
                    <button
                      className="px-3 py-1 bg-gray-100 text-gray-800 rounded-md hover:bg-gray-200"
                      onClick={() => {/* Decline connection logic */}}
                    >
                      Decline
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* Recent Sessions */}
        <div className="bg-white rounded-lg shadow-md p-6 col-span-1 md:col-span-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold">Recent Conversations</h2>
            <Link to="/sessions" className="text-teal-600 hover:text-teal-800 text-sm font-medium">
              View All
            </Link>
          </div>
          {sessionsLoading ? (
            <p className="text-gray-500">Loading sessions...</p>
          ) : recentSessions.length === 0 ? (
            <div className="text-center p-6 bg-gray-50 rounded-md">
              <p className="text-gray-500 mb-4">You haven't started any conversations yet</p>
              <Link
                to="/sessions/new"
                className="inline-block py-2 px-4 bg-teal-500 text-white rounded-md hover:bg-teal-600"
              >
                Start Your First Conversation
              </Link>
            </div>
          ) : (
            <div className="space-y-3">
              {recentSessions.map((session) => (
                <Link
                  key={session.id}
                  to={`/sessions/${session.id}`}
                  className="block p-4 border border-gray-200 rounded-md hover:bg-gray-50"
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="font-medium">
                        {session.type === 'individual'
                          ? 'Individual Session'
                          : `Session with ${session.participants
                              .filter((p) => p.user.id !== user?.id)
                              .map((p) => p.user.pseudonym)
                              .join(', ')}`}
                      </h3>
                      <p className="text-sm text-gray-500 mt-1">
                        {new Date(session.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                    <span className="px-2 py-1 bg-gray-100 text-gray-800 text-xs rounded-full">
                      {session.type}
                    </span>
                  </div>
                  {session.messages && session.messages[0] && (
                    <p className="text-gray-600 text-sm mt-2 truncate">
                      {session.messages[0].encryptedContent}
                    </p>
                  )}
                </Link>
              ))}
            </div>
          )}
        </div>

        {/* Disclaimer */}
        <div className="col-span-1 md:col-span-2 bg-gray-50 rounded-lg p-4 mt-6">
          <p className="text-xs text-gray-500 text-center">
            Remember: Coco is a supportive AI counselor, not a replacement for professional therapy.
            If you're experiencing a crisis or need professional help, please reach out to a licensed therapist or counselor.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
